/**
 * Error hierarchy and source marks, mirroring the layout of the reference
 * implementation's diagnostics (context / problem / snippet).
 */

const BREAK_OR_NUL = '\0\r\n\x85  ';

export class Mark {
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && BREAK_OR_NUL.indexOf(this.buffer[start - 1]) === -1) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && BREAK_OR_NUL.indexOf(this.buffer[end]) === -1) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end);
    return ' '.repeat(indent) + head + snippet + tail + '\n'
      + ' '.repeat(indent + this.pointer - start + head.length) + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'YAMLError';
    this.yamlClassName = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super('');
    this.context = context === undefined ? null : context;
    this.contextMark = contextMark === undefined ? null : contextMark;
    this.problem = problem === undefined ? null : problem;
    this.problemMark = problemMark === undefined ? null : problemMark;
    this.note = note === undefined ? null : note;
    this.message = this.describe();
    this.name = 'MarkedYAMLError';
    this.yamlClassName = 'yaml.error.MarkedYAMLError';
  }

  describe() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (this.contextMark !== null
      && (this.problem === null || this.problemMark === null
        || this.contextMark.name !== this.problemMark.name
        || this.contextMark.line !== this.problemMark.line
        || this.contextMark.column !== this.problemMark.column)) {
      lines.push(String(this.contextMark));
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(String(this.problemMark));
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }

  toString() {
    return this.describe();
  }
}

function marked(name, pyName) {
  const cls = class extends MarkedYAMLError {
    constructor(context, contextMark, problem, problemMark, note) {
      super(context, contextMark, problem, problemMark, note);
      this.name = name;
      this.yamlClassName = pyName;
    }
  };
  Object.defineProperty(cls, 'name', { value: name });
  return cls;
}

function plain(name, pyName) {
  const cls = class extends YAMLError {
    constructor(message) {
      super(message);
      this.name = name;
      this.yamlClassName = pyName;
    }
  };
  Object.defineProperty(cls, 'name', { value: name });
  return cls;
}

export const ScannerError = marked('ScannerError', 'yaml.scanner.ScannerError');
export const ParserError = marked('ParserError', 'yaml.parser.ParserError');
export const ComposerError = marked('ComposerError', 'yaml.composer.ComposerError');
export const ConstructorError = marked('ConstructorError', 'yaml.constructor.ConstructorError');
export const EmitterError = plain('EmitterError', 'yaml.emitter.EmitterError');
export const SerializerError = plain('SerializerError', 'yaml.serializer.SerializerError');
export const RepresenterError = plain('RepresenterError', 'yaml.representer.RepresenterError');

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.yamlName = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
    this.message = this.describe();
    this.name = 'ReaderError';
    this.yamlClassName = 'yaml.reader.ReaderError';
  }

  describe() {
    const hex = this.character.toString(16).padStart(4, '0');
    return `unacceptable character #x${hex}: ${this.reason}\n`
      + `  in "${this.yamlName}", position ${this.position}`;
  }

  toString() {
    return this.describe();
  }
}

