/**
 * Character classification helpers.
 *
 * Everything here works on single characters (or code points) through explicit
 * comparisons and lookup strings, so no pattern-matching engine is involved.
 */

export const NULL = '\0';
export const LINE_BREAKS = '\r\n\x85  ';
export const SPACES = ' \t';

/** '\0' terminator, any line break, or end of buffer. */
export function isBreakOrNull(ch) {
  return ch === '\0' || ch === '\r' || ch === '\n'
    || ch === '\x85' || ch === ' ' || ch === ' ';
}

export function isBreak(ch) {
  return ch === '\r' || ch === '\n' || ch === '\x85'
    || ch === ' ' || ch === ' ';
}

export function isSpace(ch) {
  return ch === ' ' || ch === '\t';
}

/** Whitespace, line break, or end of stream. */
export function isBlankOrNull(ch) {
  return ch === ' ' || ch === '\t' || isBreakOrNull(ch);
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function isLetterOrDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

/** Characters allowed in an anchor / alias name. */
export function isAnchorChar(ch) {
  if (isBlankOrNull(ch)) return false;
  return '?:,[]{}%@`'.indexOf(ch) === -1;
}

/** Characters allowed (unescaped) inside a tag suffix. */
export function isTagChar(ch) {
  return isLetterOrDigit(ch) || "-;/?:@&=+$,_.~*'()[]".indexOf(ch) !== -1;
}

/** Characters allowed in a tag handle body. */
export function isTagHandleChar(ch) {
  return isLetterOrDigit(ch) || ch === '-' || ch === '_';
}

export function hexValue(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'a' && ch <= 'f') return ch.charCodeAt(0) - 87;
  if (ch >= 'A' && ch <= 'F') return ch.charCodeAt(0) - 55;
  return -1;
}

/**
 * Printable per the YAML character set: #x9 | #xA | #xD | [#x20-#x7E] | #x85 |
 * [#xA0-#xD7FF] | [#xE000-#xFFFD] | [#x10000-#x10FFFF].
 */
export function isPrintableCode(code) {
  if (code === 0x09 || code === 0x0a || code === 0x0d) return true;
  if (code >= 0x20 && code <= 0x7e) return true;
  if (code === 0x85) return true;
  if (code >= 0xa0 && code <= 0xd7ff) return true;
  if (code >= 0xe000 && code <= 0xfffd) return true;
  if (code >= 0x10000 && code <= 0x10ffff) return true;
  return false;
}

/** Iterate a string by code points, yielding [codePoint, utf16Index]. */
export function* codePoints(text) {
  for (let i = 0; i < text.length;) {
    const code = text.codePointAt(i);
    yield [code, i];
    i += code > 0xffff ? 2 : 1;
  }
}

