/**
 * Character stream with mark tracking.
 *
 * The whole document is available up front (it comes from a command-line
 * argument), so the "buffer" is simply the input plus a NUL sentinel.
 */

import { ReaderError } from './errors.mjs';
import { Mark, } from './errors.mjs';
import { isPrintableCode, codePoints } from './chars.mjs';

export class Reader {
  constructor(text) {
    this.name = '<unicode string>';
    this.checkPrintable(text);
    this.buffer = text + '\0';
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
    this.eof = true;
  }

  checkPrintable(text) {
    for (const [code, i] of codePoints(text)) {
      if (!isPrintableCode(code)) {
        throw new ReaderError(this.name, i, code, 'unicode',
          'special characters are not allowed');
      }
    }
  }

  peek(index = 0) {
    const ch = this.buffer[this.pointer + index];
    return ch === undefined ? '\0' : ch;
  }

  prefix(length = 1) {
    return this.buffer.slice(this.pointer, this.pointer + length);
  }

  forward(length = 1) {
    let remaining = length;
    while (remaining > 0) {
      const ch = this.buffer[this.pointer];
      this.pointer += 1;
      this.index += 1;
      if (ch === '\n' || ch === '\x85' || ch === ' ' || ch === ' '
        || (ch === '\r' && this.buffer[this.pointer] !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== '﻿') {
        this.column += 1;
      }
      remaining -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column,
      this.buffer, this.pointer);
  }
}

