/**
 * Python-style textual reprs, used by diagnostics and by the float emitter.
 */

/** repr() of a single character, as it appears inside error messages. */
export function reprChar(ch) {
  if (ch === undefined || ch === null) return "''";
  const code = ch.codePointAt(0);
  if (ch === "'") return '"\'"';
  if (ch === '\\') return "'\\\\'";
  if (ch === '\n') return "'\\n'";
  if (ch === '\r') return "'\\r'";
  if (ch === '\t') return "'\\t'";
  if (code < 0x20 || code === 0x7f) {
    return "'\\x" + code.toString(16).padStart(2, '0') + "'";
  }
  if (code >= 0x80 && code <= 0x9f) {
    return "'\\x" + code.toString(16).padStart(2, '0') + "'";
  }
  return "'" + ch + "'";
}

/** repr() of a string, approximating CPython's rules for the common cases. */
export function reprString(text) {
  const quote = text.indexOf("'") !== -1 && text.indexOf('"') === -1 ? '"' : "'";
  let out = quote;
  for (const ch of text) {
    if (ch === quote || ch === '\\') out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else {
      const code = ch.codePointAt(0);
      if (code < 0x20 || code === 0x7f || (code >= 0x80 && code <= 0x9f)) {
        out += '\\x' + code.toString(16).padStart(2, '0');
      } else out += ch;
    }
  }
  return out + quote;
}

/**
 * Split a finite non-zero double into its shortest round-tripping decimal
 * digits and the position of the decimal point, using the platform's own
 * shortest-representation conversion as the digit source.
 */
function shortestDigits(value) {
  const text = Math.abs(value).toString();
  let digits = '';
  let exponent = 0;
  let intPart = text;
  let fracPart = '';
  let expPart = 0;
  const eAt = text.indexOf('e');
  if (eAt !== -1) {
    expPart = Number(text.slice(eAt + 1));
    intPart = text.slice(0, eAt);
  }
  const dotAt = intPart.indexOf('.');
  if (dotAt !== -1) {
    fracPart = intPart.slice(dotAt + 1);
    intPart = intPart.slice(0, dotAt);
  }
  digits = intPart + fracPart;
  // Decimal point sits after `intPart` digits, shifted by any exponent.
  exponent = intPart.length + expPart;
  // Drop leading zeros, moving the decimal point along with them.
  let lead = 0;
  while (lead < digits.length - 1 && digits[lead] === '0') lead += 1;
  digits = digits.slice(lead);
  exponent -= lead;
  // Drop trailing zeros (they carry no information for the shortest form).
  let end = digits.length;
  while (end > 1 && digits[end - 1] === '0') end -= 1;
  digits = digits.slice(0, end);
  if (digits === '0') return { digits: '0', decpt: 1 };
  return { digits, decpt: exponent };
}

function formatExponent(exp) {
  const sign = exp < 0 ? '-' : '+';
  const magnitude = Math.abs(exp);
  const text = String(magnitude);
  return 'e' + sign + (text.length < 2 ? '0' + text : text);
}

/**
 * repr() of a Python float: shortest round-tripping digits, fixed notation
 * while the decimal point stays within (-4, 17], exponential otherwise, and
 * always at least one digit after the point in fixed notation.
 */
export function reprFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  const negative = value < 0 || (value === 0 && 1 / value < 0);
  const sign = negative ? '-' : '';
  if (value === 0) return sign + '0.0';
  const { digits, decpt } = shortestDigits(value);
  if (decpt <= -4 || decpt > 16) {
    let mantissa = digits[0];
    if (digits.length > 1) mantissa += '.' + digits.slice(1);
    return sign + mantissa + formatExponent(decpt - 1);
  }
  if (decpt <= 0) {
    return sign + '0.' + '0'.repeat(-decpt) + digits;
  }
  if (decpt >= digits.length) {
    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
  }
  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

/** Zero-padded decimal, for date/time formatting. */
export function pad(value, width) {
  const text = String(value);
  return text.length >= width ? text : '0'.repeat(width - text.length) + text;
}

