/**
 * Tokenizer.
 *
 * A direct behavioural port of the reference scanner: it produces the same
 * token stream, including the synthetic block-collection tokens that come from
 * indentation tracking and the retroactive KEY tokens that come from simple-key
 * bookkeeping.
 */

import { Reader } from './reader.mjs';
import { ScannerError } from './errors.mjs';
import {
  Token, T, DirectiveToken, AnchorToken, AliasToken, TagToken, ScalarToken,
  StreamStartToken,
} from './tokens.mjs';
import { isBreak, isBreakOrNull, isBlankOrNull, isSpace, isDigit, isHexDigit, isLetterOrDigit, hexValue } from './chars.mjs';
import { reprChar } from './pyrepr.mjs';

const ESCAPE_REPLACEMENTS = new Map([
  ['0', '\0'], ['a', '\x07'], ['b', '\x08'], ['t', '\t'], ['\t', '\t'],
  ['n', '\n'], ['v', '\x0b'], ['f', '\x0c'], ['r', '\r'], ['e', '\x1b'],
  [' ', ' '], ['"', '"'], ['\\', '\\'], ['N', '\x85'], ['_', '\xa0'],
  ['L', ' '], ['P', ' '],
]);

const ESCAPE_CODES = new Map([['x', 2], ['u', 4], ['U', 8]]);

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner extends Reader {
  constructor(text) {
    super(text);
    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.fetchStreamStart();
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();
  }

  // ---- public token interface -------------------------------------------

  checkToken(...ids) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      if (ids.length === 0) return true;
      return ids.indexOf(this.tokens[0].id) !== -1;
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    return this.tokens.length ? this.tokens[0] : null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      this.tokensTaken += 1;
      return this.tokens.shift();
    }
    return null;
  }

  needMoreTokens() {
    if (this.done) return false;
    if (this.tokens.length === 0) return true;
    this.stalePossibleSimpleKeys();
    return this.nextPossibleSimpleKey() === this.tokensTaken;
  }

  fetchMoreTokens() {
    this.scanToNextToken();
    this.stalePossibleSimpleKeys();
    this.unwindIndent(this.column);
    const ch = this.peek();
    if (ch === '\0') return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowSequenceStart();
    if (ch === '{') return this.fetchFlowMappingStart();
    if (ch === ']') return this.fetchFlowSequenceEnd();
    if (ch === '}') return this.fetchFlowMappingEnd();
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && !this.flowLevel) return this.fetchLiteral();
    if (ch === '>' && !this.flowLevel) return this.fetchFolded();
    if (ch === "'") return this.fetchSingle();
    if (ch === '"') return this.fetchDouble();
    if (this.checkPlain()) return this.fetchPlain();
    throw new ScannerError('while scanning for the next token', null,
      `found character ${reprChar(ch)} that cannot start any token`,
      this.getMark());
  }

  // ---- simple keys ------------------------------------------------------

  nextPossibleSimpleKey() {
    let minTokenNumber = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (minTokenNumber === null || key.tokenNumber < minTokenNumber) {
        minTokenNumber = key.tokenNumber;
      }
    }
    return minTokenNumber;
  }

  stalePossibleSimpleKeys() {
    for (const level of Array.from(this.possibleSimpleKeys.keys())) {
      const key = this.possibleSimpleKeys.get(level);
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError('while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark());
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    const required = !this.flowLevel && this.indent === this.column;
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const tokenNumber = this.tokensTaken + this.tokens.length;
      const key = new SimpleKey(tokenNumber, required, this.index, this.line,
        this.column, this.getMark());
      this.possibleSimpleKeys.set(this.flowLevel, key);
    }
  }

  removePossibleSimpleKey() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      if (key.required) {
        throw new ScannerError('while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark());
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  // ---- indentation ------------------------------------------------------

  unwindIndent(column) {
    if (this.flowLevel) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(new Token(T.BLOCK_END, mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  // ---- fetchers ---------------------------------------------------------

  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(new StreamStartToken(mark, mark, null));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.getMark();
    this.tokens.push(new Token(T.STREAM_END, mark, mark));
    this.done = true;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
  }

  fetchDocumentStart() {
    this.fetchDocumentIndicator(T.DOCUMENT_START);
  }

  fetchDocumentEnd() {
    this.fetchDocumentIndicator(T.DOCUMENT_END);
  }

  fetchDocumentIndicator(id) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    const endMark = this.getMark();
    this.tokens.push(new Token(id, startMark, endMark));
  }

  fetchFlowSequenceStart() {
    this.fetchFlowCollectionStart(T.FLOW_SEQUENCE_START);
  }

  fetchFlowMappingStart() {
    this.fetchFlowCollectionStart(T.FLOW_MAPPING_START);
  }

  fetchFlowCollectionStart(id) {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new Token(id, startMark, endMark));
  }

  fetchFlowSequenceEnd() {
    this.fetchFlowCollectionEnd(T.FLOW_SEQUENCE_END);
  }

  fetchFlowMappingEnd() {
    this.fetchFlowCollectionEnd(T.FLOW_MAPPING_END);
  }

  fetchFlowCollectionEnd(id) {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new Token(id, startMark, endMark));
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new Token(T.FLOW_ENTRY, startMark, endMark));
  }

  fetchBlockEntry() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'sequence entries are not allowed here', this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new Token(T.BLOCK_SEQUENCE_START, mark, mark));
      }
    }
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new Token(T.BLOCK_ENTRY, startMark, endMark));
  }

  fetchKey() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'mapping keys are not allowed here', this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new Token(T.BLOCK_MAPPING_START, mark, mark));
      }
    }
    this.allowSimpleKey = false;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new Token(T.KEY, startMark, endMark));
  }

  fetchValue() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
        new Token(T.KEY, key.mark, key.mark));
      if (!this.flowLevel) {
        if (this.addIndent(key.column)) {
          this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
            new Token(T.BLOCK_MAPPING_START, key.mark, key.mark));
        }
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(null, null,
            'mapping values are not allowed here', this.getMark());
        }
        if (this.addIndent(this.column)) {
          const mark = this.getMark();
          this.tokens.push(new Token(T.BLOCK_MAPPING_START, mark, mark));
        }
      }
      this.allowSimpleKey = !this.flowLevel;
      this.removePossibleSimpleKey();
    }
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new Token(T.VALUE, startMark, endMark));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(true));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(false));
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  fetchLiteral() {
    this.fetchBlockScalar('|');
  }

  fetchFolded() {
    this.fetchBlockScalar('>');
  }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchSingle() {
    this.fetchFlowScalar("'");
  }

  fetchDouble() {
    this.fetchFlowScalar('"');
  }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  // ---- checkers ---------------------------------------------------------

  checkDirective() {
    return this.column === 0;
  }

  checkDocumentStart() {
    return this.column === 0 && this.prefix(3) === '---'
      && isBlankOrNull(this.peek(3));
  }

  checkDocumentEnd() {
    return this.column === 0 && this.prefix(3) === '...'
      && isBlankOrNull(this.peek(3));
  }

  checkBlockEntry() {
    return isBlankOrNull(this.peek(1));
  }

  checkKey() {
    if (this.flowLevel) return true;
    return isBlankOrNull(this.peek(1));
  }

  checkValue() {
    if (this.flowLevel) return true;
    return isBlankOrNull(this.peek(1));
  }

  checkPlain() {
    const ch = this.peek();
    if (!isBlankOrNull(ch) && '-?:,[]{}#&*!|>\'"%@`'.indexOf(ch) === -1) return true;
    return !isBlankOrNull(this.peek(1))
      && (ch === '-' || (!this.flowLevel && (ch === '?' || ch === ':')));
  }

  // ---- scanners ---------------------------------------------------------

  scanToNextToken() {
    if (this.index === 0 && this.peek() === '﻿') this.forward();
    let found = false;
    while (!found) {
      while (this.peek() === ' ') this.forward();
      if (this.peek() === '#') {
        while (!isBreakOrNull(this.peek())) this.forward();
      }
      if (this.scanLineBreak()) {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!isBreakOrNull(this.peek())) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return new DirectiveToken(name, value, startMark, endMark);
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isLetterOrDigit(ch) || ch === '-' || ch === '_') {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${reprChar(ch)}`,
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!(ch === '\0' || ch === ' ' || isBreak(ch))) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${reprChar(ch)}`,
        this.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or '.', but found ${reprChar(this.peek())}`,
        this.getMark());
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    const ch = this.peek();
    if (!(ch === '\0' || ch === ' ' || isBreak(ch))) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or ' ', but found ${reprChar(ch)}`, this.getMark());
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!isDigit(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit, but found ${reprChar(ch)}`, this.getMark());
    }
    let length = 0;
    while (isDigit(this.peek(length))) length += 1;
    const value = Number(this.prefix(length));
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === ' ') this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    const ch = this.peek();
    if (ch !== ' ') {
      throw new ScannerError('while scanning a directive', startMark,
        `expected ' ', but found ${reprChar(ch)}`, this.getMark());
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    const ch = this.peek();
    if (!(ch === '\0' || ch === ' ' || isBreak(ch))) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected ' ', but found ${reprChar(ch)}`, this.getMark());
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!isBreakOrNull(this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!isBreakOrNull(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a comment or a line break, but found ${reprChar(ch)}`,
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanAnchor(isAlias) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isLetterOrDigit(ch) || ch === '-' || ch === '_') {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError(`while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${reprChar(ch)}`,
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!isBlankOrNull(ch) && '?:,]}%@`'.indexOf(ch) === -1) {
      throw new ScannerError(`while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${reprChar(ch)}`,
        this.getMark());
    }
    const endMark = this.getMark();
    return isAlias ? new AliasToken(value, startMark, endMark)
      : new AnchorToken(value, startMark, endMark);
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle = null;
    let suffix;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError('while parsing a tag', startMark,
          `expected '>', but found ${reprChar(this.peek())}`, this.getMark());
      }
      this.forward();
    } else if (isBlankOrNull(ch)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!(ch === '\0' || ch === ' ' || isBreak(ch))) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!(ch === '\0' || ch === ' ' || isBreak(ch))) {
      throw new ScannerError('while scanning a tag', startMark,
        `expected ' ', but found ${reprChar(ch)}`, this.getMark());
    }
    const endMark = this.getMark();
    return new TagToken([handle, suffix], startMark, endMark);
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();
    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);
    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let indent;
    let breaks;
    let endMark;
    if (increment === null) {
      const found = this.scanBlockScalarIndentation();
      breaks = found[0];
      endMark = found[2];
      indent = Math.max(minIndent, found[1]);
    } else {
      indent = minIndent + increment - 1;
      const found = this.scanBlockScalarBreaks(indent);
      breaks = found[0];
      endMark = found[1];
    }
    let lineBreak = '';
    while (this.column === indent && this.peek() !== '\0') {
      for (const item of breaks) chunks.push(item);
      const leadingNonSpace = !isSpace(this.peek());
      let length = 0;
      while (!isBreakOrNull(this.peek(length))) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const found = this.scanBlockScalarBreaks(indent);
      breaks = found[0];
      endMark = found[1];
      if (this.column === indent && this.peek() !== '\0') {
        if (folded && lineBreak === '\n' && leadingNonSpace && !isSpace(this.peek())) {
          if (!breaks.length) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }
    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) {
      for (const item of breaks) chunks.push(item);
    }
    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (isDigit(ch)) {
        increment = Number(ch);
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0',
            this.getMark());
        }
        this.forward();
      }
    } else if (isDigit(ch)) {
      increment = Number(ch);
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0',
          this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!(ch === '\0' || ch === ' ' || isBreak(ch))) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected chomping or indentation indicators, but found ${reprChar(ch)}`,
        this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!isBreakOrNull(this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!isBreakOrNull(ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected a comment or a line break, but found ${reprChar(ch)}`,
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (this.peek() === ' ' || isBreak(this.peek())) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') this.forward();
    while (isBreak(this.peek())) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    for (const item of this.scanFlowScalarNonSpaces(double, startMark)) chunks.push(item);
    while (this.peek() !== quote) {
      for (const item of this.scanFlowScalarSpaces(double, startMark)) chunks.push(item);
      for (const item of this.scanFlowScalarNonSpaces(double, startMark)) chunks.push(item);
    }
    this.forward();
    const endMark = this.getMark();
    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      for (;;) {
        const c = this.peek(length);
        if (c === "'" || c === '"' || c === '\\' || isBlankOrNull(c)) break;
        length += 1;
      }
      if (length) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === "'" && this.peek(1) === "'") {
        chunks.push("'");
        this.forward(2);
      } else if ((double && ch === "'") || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (ESCAPE_REPLACEMENTS.has(ch)) {
          chunks.push(ESCAPE_REPLACEMENTS.get(ch));
          this.forward();
        } else if (ESCAPE_CODES.has(ch)) {
          const length2 = ESCAPE_CODES.get(ch);
          this.forward();
          for (let k = 0; k < length2; k += 1) {
            if (!isHexDigit(this.peek(k))) {
              throw new ScannerError('while scanning a double-quoted scalar',
                startMark,
                `expected escape sequence of ${length2} hexdecimal numbers, but found ${reprChar(this.peek(k))}`,
                this.getMark());
            }
          }
          let code = 0;
          for (let k = 0; k < length2; k += 1) code = code * 16 + hexValue(this.peek(k));
          chunks.push(codePointToString(code, startMark, this.getMark()));
          this.forward(length2);
        } else if (isBreak(ch)) {
          this.scanLineBreak();
          for (const item of this.scanFlowScalarBreaks(double, startMark)) chunks.push(item);
        } else {
          throw new ScannerError('while scanning a double-quoted scalar',
            startMark, `found unknown escape character ${reprChar(ch)}`,
            this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (isSpace(this.peek(length))) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === '\0') {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    }
    if (isBreak(ch)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (!breaks.length) chunks.push(' ');
      for (const item of breaks) chunks.push(item);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && isBlankOrNull(this.peek(3))) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark());
      }
      while (isSpace(this.peek())) this.forward();
      if (isBreak(this.peek())) {
        chunks.push(this.scanLineBreak());
      } else {
        return chunks;
      }
    }
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      let length = 0;
      if (this.peek() === '#') break;
      for (;;) {
        const ch = this.peek(length);
        const next = this.peek(length + 1);
        if (isBlankOrNull(ch)
          || (ch === ':' && (isBlankOrNull(next)
            || (this.flowLevel && ',[]{}'.indexOf(next) !== -1)))
          || (this.flowLevel && ',?[]{}'.indexOf(ch) !== -1)) {
          break;
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      for (const item of spaces) chunks.push(item);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (!spaces || spaces.length === 0 || this.peek() === '#'
        || (!this.flowLevel && this.column < indent)) {
        break;
      }
    }
    return new ScalarToken(chunks.join(''), true, startMark, endMark, null);
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (isBreak(ch)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && isBlankOrNull(this.peek(3))) {
        return [];
      }
      const breaks = [];
      while (this.peek() === ' ' || isBreak(this.peek())) {
        if (this.peek() === ' ') {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.prefix(3);
          if ((prefix === '---' || prefix === '...') && isBlankOrNull(this.peek(3))) {
            return [];
          }
        }
      }
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (!breaks.length) chunks.push(' ');
      for (const item of breaks) chunks.push(item);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        `expected '!', but found ${reprChar(ch)}`, this.getMark());
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== ' ') {
      while (isLetterOrDigit(ch) || ch === '-' || ch === '_') {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError(`while scanning a ${name}`, startMark,
          `expected '!', but found ${reprChar(ch)}`, this.getMark());
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (isLetterOrDigit(ch) || "-;/?:@&=+$,_.!~*'()[]%".indexOf(ch) !== -1) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (!chunks.length) {
      throw new ScannerError(`while parsing a ${name}`, startMark,
        `expected URI, but found ${reprChar(ch)}`, this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const bytes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k += 1) {
        if (!isHexDigit(this.peek(k))) {
          throw new ScannerError(`while scanning a ${name}`, startMark,
            `expected URI escape sequence of 2 hexdecimal numbers, but found ${reprChar(this.peek(k))}`,
            this.getMark());
        }
      }
      bytes.push(hexValue(this.peek(0)) * 16 + hexValue(this.peek(1)));
      this.forward(2);
    }
    try {
      return decodeUtf8(bytes);
    } catch (err) {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        String(err && err.message ? err.message : err), mark);
    }
  }

  scanLineBreak() {
    const ch = this.peek();
    if (ch === '\r' || ch === '\n' || ch === '\x85') {
      if (this.prefix(2) === '\r\n') this.forward(2);
      else this.forward();
      return '\n';
    }
    if (ch === ' ' || ch === ' ') {
      this.forward();
      return ch;
    }
    return '';
  }
}

function codePointToString(code, startMark, mark) {
  if (code > 0x10ffff) {
    throw new ScannerError('while scanning a double-quoted scalar', startMark,
      'found unknown escape character', mark);
  }
  return String.fromCodePoint(code);
}

/** Minimal UTF-8 decoder for percent-escaped tag URIs. */
function decodeUtf8(bytes) {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const b0 = bytes[i];
    let code;
    let extra;
    if (b0 < 0x80) {
      code = b0;
      extra = 0;
    } else if (b0 >= 0xc2 && b0 <= 0xdf) {
      code = b0 & 0x1f;
      extra = 1;
    } else if (b0 >= 0xe0 && b0 <= 0xef) {
      code = b0 & 0x0f;
      extra = 2;
    } else if (b0 >= 0xf0 && b0 <= 0xf4) {
      code = b0 & 0x07;
      extra = 3;
    } else {
      throw new Error(`'utf-8' codec can't decode byte 0x${b0.toString(16)}: invalid start byte`);
    }
    if (i + extra >= bytes.length + 0 && extra > 0 && i + extra > bytes.length - 1) {
      throw new Error("'utf-8' codec can't decode bytes: unexpected end of data");
    }
    for (let k = 1; k <= extra; k += 1) {
      const b = bytes[i + k];
      if (b === undefined || (b & 0xc0) !== 0x80) {
        throw new Error(`'utf-8' codec can't decode byte 0x${b0.toString(16)}: invalid continuation byte`);
      }
      code = (code << 6) | (b & 0x3f);
    }
    out += String.fromCodePoint(code);
    i += extra + 1;
  }
  return out;
}

