/**
 * Parser events and their identifiers.
 */

export const E = {
  STREAM_START: 'stream-start',
  STREAM_END: 'stream-end',
  DOCUMENT_START: 'document-start',
  DOCUMENT_END: 'document-end',
  ALIAS: 'alias',
  SCALAR: 'scalar',
  SEQUENCE_START: 'sequence-start',
  SEQUENCE_END: 'sequence-end',
  MAPPING_START: 'mapping-start',
  MAPPING_END: 'mapping-end',
};

export class Event {
  constructor(id, startMark = null, endMark = null) {
    this.id = id;
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

export class StreamStartEvent extends Event {
  constructor(startMark = null, endMark = null, encoding = null) {
    super(E.STREAM_START, startMark, endMark);
    this.encoding = encoding;
  }
}

export class StreamEndEvent extends Event {
  constructor(startMark = null, endMark = null) {
    super(E.STREAM_END, startMark, endMark);
  }
}

export class DocumentStartEvent extends Event {
  constructor(startMark = null, endMark = null, explicit = null, version = null, tags = null) {
    super(E.DOCUMENT_START, startMark, endMark);
    this.explicit = explicit;
    this.version = version;
    this.tags = tags;
  }
}

export class DocumentEndEvent extends Event {
  constructor(startMark = null, endMark = null, explicit = null) {
    super(E.DOCUMENT_END, startMark, endMark);
    this.explicit = explicit;
  }
}

export class AliasEvent extends Event {
  constructor(anchor, startMark = null, endMark = null) {
    super(E.ALIAS, startMark, endMark);
    this.anchor = anchor;
  }
}

export class ScalarEvent extends Event {
  constructor(anchor, tag, implicit, value, startMark = null, endMark = null, style = null) {
    super(E.SCALAR, startMark, endMark);
    this.anchor = anchor;
    this.tag = tag;
    this.implicit = implicit;
    this.value = value;
    this.style = style;
  }
}

export class SequenceStartEvent extends Event {
  constructor(anchor, tag, implicit, startMark = null, endMark = null, flowStyle = null) {
    super(E.SEQUENCE_START, startMark, endMark);
    this.anchor = anchor;
    this.tag = tag;
    this.implicit = implicit;
    this.flowStyle = flowStyle;
  }
}

export class SequenceEndEvent extends Event {
  constructor(startMark = null, endMark = null) {
    super(E.SEQUENCE_END, startMark, endMark);
  }
}

export class MappingStartEvent extends Event {
  constructor(anchor, tag, implicit, startMark = null, endMark = null, flowStyle = null) {
    super(E.MAPPING_START, startMark, endMark);
    this.anchor = anchor;
    this.tag = tag;
    this.implicit = implicit;
    this.flowStyle = flowStyle;
  }
}

export class MappingEndEvent extends Event {
  constructor(startMark = null, endMark = null) {
    super(E.MAPPING_END, startMark, endMark);
  }
}

