/**
 * Representation graph nodes.
 */

export const SCALAR = 'scalar';
export const SEQUENCE = 'sequence';
export const MAPPING = 'mapping';

export class Node {
  constructor(kind, tag, value, startMark = null, endMark = null) {
    this.kind = kind;
    this.tag = tag;
    this.value = value;
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

export class ScalarNode extends Node {
  constructor(tag, value, startMark = null, endMark = null, style = null) {
    super(SCALAR, tag, value, startMark, endMark);
    this.style = style;
  }
}

export class SequenceNode extends Node {
  constructor(tag, value, startMark = null, endMark = null, flowStyle = null) {
    super(SEQUENCE, tag, value, startMark, endMark);
    this.flowStyle = flowStyle;
  }
}

export class MappingNode extends Node {
  constructor(tag, value, startMark = null, endMark = null, flowStyle = null) {
    super(MAPPING, tag, value, startMark, endMark);
    this.flowStyle = flowStyle;
  }
}

