/**
 * Event parser.
 *
 * The grammar is driven by an explicit state stack, matching the reference
 * implementation's production names so that error messages line up.
 */

import { Scanner } from './scanner.mjs';
import { ParserError } from './errors.mjs';
import { T } from './tokens.mjs';
import {
  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
  MappingStartEvent, MappingEndEvent,
} from './events.mjs';
import { reprString } from './pyrepr.mjs';

const DEFAULT_TAGS = new Map([['!', '!'], ['!!', 'tag:yaml.org,2002:']]);

export class Parser extends Scanner {
  constructor(text) {
    super(text);
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = new Map();
    this.states = [];
    this.marks = [];
    this.state = 'parseStreamStart';
  }

  step() {
    return this[this.state]();
  }

  checkEvent(...ids) {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.step();
    }
    if (this.currentEvent !== null) {
      if (ids.length === 0) return true;
      return ids.indexOf(this.currentEvent.id) !== -1;
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.step();
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.step();
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  // ---- stream / document -------------------------------------------------

  parseStreamStart() {
    const token = this.getToken();
    const event = new StreamStartEvent(token.startMark, token.endMark, token.encoding);
    this.state = 'parseImplicitDocumentStart';
    return event;
  }

  parseImplicitDocumentStart() {
    if (!this.checkToken(T.DIRECTIVE, T.DOCUMENT_START, T.STREAM_END)) {
      this.tagHandles = new Map(DEFAULT_TAGS);
      const token = this.peekToken();
      const startMark = token.startMark;
      const event = new DocumentStartEvent(startMark, startMark, false);
      this.states.push('parseDocumentEnd');
      this.state = 'parseBlockNode';
      return event;
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.checkToken(T.DOCUMENT_END)) this.getToken();
    let event;
    if (!this.checkToken(T.STREAM_END)) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken(T.DOCUMENT_START)) {
        throw new ParserError(null, null,
          `expected '<document start>', but found ${reprString(this.peekToken().id)}`,
          this.peekToken().startMark);
      }
      token = this.getToken();
      event = new DocumentStartEvent(startMark, token.endMark, true, version, tags);
      this.states.push('parseDocumentEnd');
      this.state = 'parseDocumentContent';
    } else {
      const token = this.getToken();
      event = new StreamEndEvent(token.startMark, token.endMark);
      this.state = null;
    }
    return event;
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = token.startMark;
    let explicit = false;
    if (this.checkToken(T.DOCUMENT_END)) {
      token = this.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    const event = new DocumentEndEvent(startMark, endMark, explicit);
    this.state = 'parseDocumentStart';
    return event;
  }

  parseDocumentContent() {
    if (this.checkToken(T.DIRECTIVE, T.DOCUMENT_START, T.DOCUMENT_END, T.STREAM_END)) {
      const event = this.processEmptyScalar(this.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = new Map();
    while (this.checkToken(T.DIRECTIVE)) {
      const token = this.getToken();
      if (token.name === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive',
            token.startMark);
        }
        const [major] = token.value;
        if (major !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark);
        }
        this.yamlVersion = token.value;
      } else if (token.name === 'TAG') {
        const [handle, prefix] = token.value;
        if (this.tagHandles.has(handle)) {
          throw new ParserError(null, null,
            `duplicate tag handle ${reprString(handle)}`, token.startMark);
        }
        this.tagHandles.set(handle, prefix);
      }
    }
    const value = this.tagHandles.size
      ? [this.yamlVersion, new Map(this.tagHandles)]
      : [this.yamlVersion, null];
    for (const [key, prefix] of DEFAULT_TAGS) {
      if (!this.tagHandles.has(key)) this.tagHandles.set(key, prefix);
    }
    return value;
  }

  // ---- nodes ------------------------------------------------------------

  parseBlockNode() {
    return this.parseNode(true, false);
  }

  parseFlowNode() {
    return this.parseNode(false, false);
  }

  parseBlockNodeOrIndentlessSequence() {
    return this.parseNode(true, true);
  }

  parseNode(block = false, indentlessSequence = false) {
    if (this.checkToken(T.ALIAS)) {
      const token = this.getToken();
      const event = new AliasEvent(token.value, token.startMark, token.endMark);
      this.state = this.states.pop();
      return event;
    }
    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    if (this.checkToken(T.ANCHOR)) {
      let token = this.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.checkToken(T.TAG)) {
        token = this.getToken();
        tagMark = token.startMark;
        endMark = token.endMark;
        tag = token.value;
      }
    } else if (this.checkToken(T.TAG)) {
      let token = this.getToken();
      startMark = token.startMark;
      tagMark = token.startMark;
      endMark = token.endMark;
      tag = token.value;
      if (this.checkToken(T.ANCHOR)) {
        token = this.getToken();
        endMark = token.endMark;
        anchor = token.value;
      }
    }
    if (tag !== null) {
      const [handle, suffix] = tag;
      if (handle !== null) {
        if (!this.tagHandles.has(handle)) {
          throw new ParserError('while parsing a node', startMark,
            `found undefined tag handle ${reprString(handle)}`, tagMark);
        }
        tag = this.tagHandles.get(handle) + suffix;
      } else {
        tag = suffix;
      }
    }
    if (startMark === null) {
      startMark = this.peekToken().startMark;
      endMark = startMark;
    }
    let event = null;
    const implicit = tag === null || tag === '!';
    if (indentlessSequence && this.checkToken(T.BLOCK_ENTRY)) {
      endMark = this.peekToken().endMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, null);
      this.state = 'parseIndentlessSequenceEntry';
      return event;
    }
    if (this.checkToken(T.SCALAR)) {
      const token = this.getToken();
      endMark = token.endMark;
      let scalarImplicit;
      if ((token.plain && tag === null) || tag === '!') scalarImplicit = [true, false];
      else if (tag === null) scalarImplicit = [false, true];
      else scalarImplicit = [false, false];
      event = new ScalarEvent(anchor, tag, scalarImplicit, token.value,
        startMark, endMark, token.style);
      this.state = this.states.pop();
      return event;
    }
    if (this.checkToken(T.FLOW_SEQUENCE_START)) {
      endMark = this.peekToken().endMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, true);
      this.state = 'parseFlowSequenceFirstEntry';
      return event;
    }
    if (this.checkToken(T.FLOW_MAPPING_START)) {
      endMark = this.peekToken().endMark;
      event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, true);
      this.state = 'parseFlowMappingFirstKey';
      return event;
    }
    if (block && this.checkToken(T.BLOCK_SEQUENCE_START)) {
      endMark = this.peekToken().startMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, false);
      this.state = 'parseBlockSequenceFirstEntry';
      return event;
    }
    if (block && this.checkToken(T.BLOCK_MAPPING_START)) {
      endMark = this.peekToken().startMark;
      event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, false);
      this.state = 'parseBlockMappingFirstKey';
      return event;
    }
    if (anchor !== null || tag !== null) {
      event = new ScalarEvent(anchor, tag, [implicit, false], '', startMark, endMark);
      this.state = this.states.pop();
      return event;
    }
    const node = block ? 'block' : 'flow';
    const token = this.peekToken();
    throw new ParserError(`while parsing a ${node} node`, startMark,
      `expected the node content, but found ${reprString(token.id)}`,
      token.startMark);
  }

  // ---- block collections ------------------------------------------------

  parseBlockSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockSequenceEntry();
  }

  parseBlockSequenceEntry() {
    if (this.checkToken(T.BLOCK_ENTRY)) {
      const token = this.getToken();
      if (!this.checkToken(T.BLOCK_ENTRY, T.BLOCK_END)) {
        this.states.push('parseBlockSequenceEntry');
        return this.parseBlockNode();
      }
      this.state = 'parseBlockSequenceEntry';
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken(T.BLOCK_END)) {
      const token = this.peekToken();
      throw new ParserError('while parsing a block collection',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found ${reprString(token.id)}`, token.startMark);
    }
    const token = this.getToken();
    const event = new SequenceEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseIndentlessSequenceEntry() {
    if (this.checkToken(T.BLOCK_ENTRY)) {
      const token = this.getToken();
      if (!this.checkToken(T.BLOCK_ENTRY, T.KEY, T.VALUE, T.BLOCK_END)) {
        this.states.push('parseIndentlessSequenceEntry');
        return this.parseBlockNode();
      }
      this.state = 'parseIndentlessSequenceEntry';
      return this.processEmptyScalar(token.endMark);
    }
    const token = this.peekToken();
    const event = new SequenceEndEvent(token.startMark, token.startMark);
    this.state = this.states.pop();
    return event;
  }

  parseBlockMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockMappingKey();
  }

  parseBlockMappingKey() {
    if (this.checkToken(T.KEY)) {
      const token = this.getToken();
      if (!this.checkToken(T.KEY, T.VALUE, T.BLOCK_END)) {
        this.states.push('parseBlockMappingValue');
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = 'parseBlockMappingValue';
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken(T.BLOCK_END)) {
      const token = this.peekToken();
      throw new ParserError('while parsing a block mapping',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found ${reprString(token.id)}`, token.startMark);
    }
    const token = this.getToken();
    const event = new MappingEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseBlockMappingValue() {
    if (this.checkToken(T.VALUE)) {
      const token = this.getToken();
      if (!this.checkToken(T.KEY, T.VALUE, T.BLOCK_END)) {
        this.states.push('parseBlockMappingKey');
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = 'parseBlockMappingKey';
      return this.processEmptyScalar(token.endMark);
    }
    this.state = 'parseBlockMappingKey';
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  // ---- flow collections -------------------------------------------------

  parseFlowSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowSequenceEntry(true);
  }

  parseFlowSequenceEntry(first = false) {
    if (!this.checkToken(T.FLOW_SEQUENCE_END)) {
      if (!first) {
        if (this.checkToken(T.FLOW_ENTRY)) {
          this.getToken();
        } else {
          const token = this.peekToken();
          throw new ParserError('while parsing a flow sequence',
            this.marks[this.marks.length - 1],
            `expected ',' or ']', but got ${reprString(token.id)}`, token.startMark);
        }
      }
      if (this.checkToken(T.KEY)) {
        const token = this.peekToken();
        const event = new MappingStartEvent(null, null, true,
          token.startMark, token.endMark, true);
        this.state = 'parseFlowSequenceEntryMappingKey';
        return event;
      }
      if (!this.checkToken(T.FLOW_SEQUENCE_END)) {
        this.states.push('parseFlowSequenceEntryContinue');
        return this.parseFlowNode();
      }
    }
    const token = this.getToken();
    const event = new SequenceEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseFlowSequenceEntryContinue() {
    return this.parseFlowSequenceEntry(false);
  }

  parseFlowSequenceEntryMappingKey() {
    const token = this.getToken();
    if (!this.checkToken(T.VALUE, T.FLOW_ENTRY, T.FLOW_SEQUENCE_END)) {
      this.states.push('parseFlowSequenceEntryMappingValue');
      return this.parseFlowNode();
    }
    this.state = 'parseFlowSequenceEntryMappingValue';
    return this.processEmptyScalar(token.endMark);
  }

  parseFlowSequenceEntryMappingValue() {
    if (this.checkToken(T.VALUE)) {
      const token = this.getToken();
      if (!this.checkToken(T.FLOW_ENTRY, T.FLOW_SEQUENCE_END)) {
        this.states.push('parseFlowSequenceEntryMappingEnd');
        return this.parseFlowNode();
      }
      this.state = 'parseFlowSequenceEntryMappingEnd';
      return this.processEmptyScalar(token.endMark);
    }
    this.state = 'parseFlowSequenceEntryMappingEnd';
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  parseFlowSequenceEntryMappingEnd() {
    this.state = 'parseFlowSequenceEntryContinue';
    const token = this.peekToken();
    return new MappingEndEvent(token.startMark, token.startMark);
  }

  parseFlowMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowMappingKey(true);
  }

  parseFlowMappingKey(first = false) {
    if (!this.checkToken(T.FLOW_MAPPING_END)) {
      if (!first) {
        if (this.checkToken(T.FLOW_ENTRY)) {
          this.getToken();
        } else {
          const token = this.peekToken();
          throw new ParserError('while parsing a flow mapping',
            this.marks[this.marks.length - 1],
            `expected ',' or '}', but got ${reprString(token.id)}`, token.startMark);
        }
      }
      if (this.checkToken(T.KEY)) {
        const token = this.getToken();
        if (!this.checkToken(T.VALUE, T.FLOW_ENTRY, T.FLOW_MAPPING_END)) {
          this.states.push('parseFlowMappingValue');
          return this.parseFlowNode();
        }
        this.state = 'parseFlowMappingValue';
        return this.processEmptyScalar(token.endMark);
      }
      if (!this.checkToken(T.FLOW_MAPPING_END)) {
        this.states.push('parseFlowMappingEmptyValue');
        return this.parseFlowNode();
      }
    }
    const token = this.getToken();
    const event = new MappingEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseFlowMappingKeyContinue() {
    return this.parseFlowMappingKey(false);
  }

  parseFlowMappingValue() {
    if (this.checkToken(T.VALUE)) {
      const token = this.getToken();
      if (!this.checkToken(T.FLOW_ENTRY, T.FLOW_MAPPING_END)) {
        this.states.push('parseFlowMappingKeyContinue');
        return this.parseFlowNode();
      }
      this.state = 'parseFlowMappingKeyContinue';
      return this.processEmptyScalar(token.endMark);
    }
    this.state = 'parseFlowMappingKeyContinue';
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  parseFlowMappingEmptyValue() {
    this.state = 'parseFlowMappingKeyContinue';
    return this.processEmptyScalar(this.peekToken().startMark);
  }

  processEmptyScalar(mark) {
    return new ScalarEvent(null, null, [true, false], '', mark, mark);
  }
}

