/**
 * Implicit tag resolution.
 *
 * The reference implementation drives this with compiled patterns; here each
 * pattern is expressed as a hand-written character matcher, keyed by first
 * character in registration order so that precedence is preserved.
 */

import { SCALAR, SEQUENCE, MAPPING } from './nodes.mjs';
import { isDigit, isHexDigit } from './chars.mjs';

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

const BOOL_WORDS = [
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
];

const NULL_WORDS = ['~', 'null', 'Null', 'NULL', ''];

function matchBool(value) {
  return BOOL_WORDS.indexOf(value) !== -1;
}

function matchNull(value) {
  return NULL_WORDS.indexOf(value) !== -1;
}

function matchMerge(value) {
  return value === '<<';
}

function matchValueTag(value) {
  return value === '=';
}

function matchYamlTag(value) {
  return value === '!' || value === '&' || value === '*';
}

/** Cursor helpers: each returns the new position, or -1 when not matched. */
function eatSign(text, i) {
  const ch = text[i];
  return (ch === '-' || ch === '+') ? i + 1 : i;
}

function eatDigits(text, i, allowUnderscore, minCount) {
  let j = i;
  let count = 0;
  while (j < text.length && (isDigit(text[j]) || (allowUnderscore && text[j] === '_'))) {
    if (isDigit(text[j])) count += 1;
    j += 1;
  }
  if (j - i < minCount) return -1;
  return j;
}

/** [0-9][0-9_]* — must start with a digit. */
function eatDigitRun(text, i) {
  if (i >= text.length || !isDigit(text[i])) return -1;
  let j = i + 1;
  while (j < text.length && (isDigit(text[j]) || text[j] === '_')) j += 1;
  return j;
}

/** [0-9_]* — possibly empty. */
function eatDigitOrUnderscoreRun(text, i) {
  let j = i;
  while (j < text.length && (isDigit(text[j]) || text[j] === '_')) j += 1;
  return j;
}

/** (?:[eE][-+][0-9]+)? — the sign is mandatory when an exponent is present. */
function eatExponent(text, i) {
  if (i >= text.length) return i;
  if (text[i] !== 'e' && text[i] !== 'E') return i;
  let j = i + 1;
  if (j >= text.length || (text[j] !== '-' && text[j] !== '+')) return -1;
  j += 1;
  const start = j;
  while (j < text.length && isDigit(text[j])) j += 1;
  if (j === start) return -1;
  return j;
}

/** (:[0-5]?[0-9])+ */
function eatSexagesimal(text, i) {
  let j = i;
  let groups = 0;
  while (j < text.length && text[j] === ':') {
    let k = j + 1;
    if (k < text.length && text[k] >= '0' && text[k] <= '5' && k + 1 < text.length
      && isDigit(text[k + 1])) {
      k += 2;
    } else if (k < text.length && isDigit(text[k])) {
      k += 1;
    } else {
      return -1;
    }
    j = k;
    groups += 1;
  }
  return groups > 0 ? j : -1;
}

function matchFloat(value) {
  if (value.length === 0) return false;
  // [-+]?\.(?:inf|Inf|INF)
  {
    let i = eatSign(value, 0);
    if (value[i] === '.') {
      const rest = value.slice(i + 1);
      if (rest === 'inf' || rest === 'Inf' || rest === 'INF') return true;
    }
  }
  // \.(?:nan|NaN|NAN)
  if (value === '.nan' || value === '.NaN' || value === '.NAN') return true;
  // [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
  {
    const i = eatSign(value, 0);
    let j = eatDigitRun(value, i);
    if (j !== -1) {
      const k = eatSexagesimal(value, j);
      if (k !== -1 && value[k] === '.') {
        const end = eatDigitOrUnderscoreRun(value, k + 1);
        if (end === value.length) return true;
      }
    }
  }
  // [-+]?[0-9][0-9_]*\.[0-9_]*(?:[eE][-+][0-9]+)?
  {
    const i = eatSign(value, 0);
    const j = eatDigitRun(value, i);
    if (j !== -1 && value[j] === '.') {
      const k = eatDigitOrUnderscoreRun(value, j + 1);
      const end = eatExponent(value, k);
      if (end === value.length) return true;
    }
  }
  // \.[0-9_]+(?:[eE][-+][0-9]+)?
  if (value[0] === '.') {
    const k = eatDigits(value, 1, true, 1);
    if (k !== -1) {
      const end = eatExponent(value, k);
      if (end === value.length) return true;
    }
  }
  return false;
}

function matchInt(value) {
  if (value.length === 0) return false;
  const i = eatSign(value, 0);
  const body = value.slice(i);
  if (body.length === 0) return false;
  // 0b[0-1_]+
  if (body.length > 2 && body[0] === '0' && body[1] === 'b') {
    let count = 0;
    for (let k = 2; k < body.length; k += 1) {
      const ch = body[k];
      if (ch === '0' || ch === '1') count += 1;
      else if (ch !== '_') return false;
    }
    if (count > 0 || body.length > 2) return true;
  }
  // 0x[0-9a-fA-F_]+
  if (body.length > 2 && body[0] === '0' && body[1] === 'x') {
    let ok = true;
    for (let k = 2; k < body.length; k += 1) {
      const ch = body[k];
      if (!isHexDigit(ch) && ch !== '_') { ok = false; break; }
    }
    if (ok) return true;
  }
  // 0[0-7_]+
  if (body.length > 1 && body[0] === '0') {
    let ok = true;
    for (let k = 1; k < body.length; k += 1) {
      const ch = body[k];
      if (!(ch >= '0' && ch <= '7') && ch !== '_') { ok = false; break; }
    }
    if (ok) return true;
  }
  // (0|[1-9][0-9_]*)
  if (body === '0') return true;
  if (body[0] >= '1' && body[0] <= '9') {
    let k = 1;
    while (k < body.length && (isDigit(body[k]) || body[k] === '_')) k += 1;
    if (k === body.length) return true;
    // [1-9][0-9_]*(:[0-5]?[0-9])+
    const end = eatSexagesimal(body, k);
    if (end === body.length) return true;
  }
  return false;
}

function matchTwoDigits(text, i) {
  return i + 1 < text.length && isDigit(text[i]) && isDigit(text[i + 1]);
}

function matchTimestamp(value) {
  // yyyy-mm-dd
  if (value.length === 10 && matchTwoDigits(value, 0) && matchTwoDigits(value, 2)
    && value[4] === '-' && matchTwoDigits(value, 5) && value[7] === '-'
    && matchTwoDigits(value, 8)) {
    return true;
  }
  return parseTimestampParts(value) !== null;
}

/**
 * Full timestamp grammar with optional time, fraction and zone.
 * Returns the captured parts, or null when the text does not match.
 */
export function parseTimestampParts(value) {
  let i = 0;
  if (!(matchTwoDigits(value, 0) && matchTwoDigits(value, 2))) return null;
  const year = value.slice(0, 4);
  i = 4;
  if (value[i] !== '-') return null;
  i += 1;
  let start = i;
  if (i < value.length && isDigit(value[i])) i += 1; else return null;
  if (i < value.length && isDigit(value[i])) i += 1;
  const month = value.slice(start, i);
  if (value[i] !== '-') return null;
  i += 1;
  start = i;
  if (i < value.length && isDigit(value[i])) i += 1; else return null;
  if (i < value.length && isDigit(value[i])) i += 1;
  const day = value.slice(start, i);
  if (i === value.length) {
    return { year, month, day, hour: null, minute: null, second: null, fraction: null, tz: null, tzSign: null, tzHour: null, tzMinute: null };
  }
  // Separator between date and time.
  if (value[i] === 'T' || value[i] === 't') {
    i += 1;
  } else if (value[i] === ' ' || value[i] === '\t') {
    while (i < value.length && (value[i] === ' ' || value[i] === '\t')) i += 1;
  } else {
    return null;
  }
  start = i;
  if (i < value.length && isDigit(value[i])) i += 1; else return null;
  if (i < value.length && isDigit(value[i])) i += 1;
  const hour = value.slice(start, i);
  if (value[i] !== ':') return null;
  i += 1;
  if (!matchTwoDigits(value, i)) return null;
  const minute = value.slice(i, i + 2);
  i += 2;
  if (value[i] !== ':') return null;
  i += 1;
  if (!matchTwoDigits(value, i)) return null;
  const second = value.slice(i, i + 2);
  i += 2;
  let fraction = null;
  if (i < value.length && value[i] === '.') {
    i += 1;
    start = i;
    while (i < value.length && isDigit(value[i])) i += 1;
    fraction = value.slice(start, i);
  }
  let tz = null;
  let tzSign = null;
  let tzHour = null;
  let tzMinute = null;
  if (i < value.length) {
    let j = i;
    while (j < value.length && (value[j] === ' ' || value[j] === '\t')) j += 1;
    if (j < value.length && value[j] === 'Z') {
      tz = 'Z';
      j += 1;
    } else if (j < value.length && (value[j] === '-' || value[j] === '+')) {
      tzSign = value[j];
      j += 1;
      start = j;
      if (j < value.length && isDigit(value[j])) j += 1; else return null;
      if (j < value.length && isDigit(value[j])) j += 1;
      tzHour = value.slice(start, j);
      if (j < value.length && value[j] === ':') {
        j += 1;
        if (!matchTwoDigits(value, j)) return null;
        tzMinute = value.slice(j, j + 2);
        j += 2;
      }
      tz = tzSign + tzHour + (tzMinute === null ? '' : ':' + tzMinute);
    } else {
      return null;
    }
    i = j;
  }
  if (i !== value.length) return null;
  return { year, month, day, hour, minute, second, fraction, tz, tzSign, tzHour, tzMinute };
}

/** Registration order decides precedence when several patterns share a lead character. */
const RESOLVERS = [
  { tag: 'tag:yaml.org,2002:bool', match: matchBool, first: 'yYnNtTfFoO' },
  { tag: 'tag:yaml.org,2002:float', match: matchFloat, first: '-+0123456789.' },
  { tag: 'tag:yaml.org,2002:int', match: matchInt, first: '-+0123456789' },
  { tag: 'tag:yaml.org,2002:merge', match: matchMerge, first: '<' },
  { tag: 'tag:yaml.org,2002:null', match: matchNull, first: '~nN\0' },
  { tag: 'tag:yaml.org,2002:timestamp', match: matchTimestamp, first: '0123456789' },
  { tag: 'tag:yaml.org,2002:value', match: matchValueTag, first: '=' },
  { tag: 'tag:yaml.org,2002:yaml', match: matchYamlTag, first: '!&*' },
];

const BY_FIRST = new Map();
for (const entry of RESOLVERS) {
  for (const ch of entry.first) {
    const key = ch === '\0' ? '' : ch;
    if (!BY_FIRST.has(key)) BY_FIRST.set(key, []);
    BY_FIRST.get(key).push(entry);
  }
}

export function resolve(kind, value, implicit) {
  if (kind === SCALAR && implicit[0]) {
    const key = value.length === 0 ? '' : value[0];
    const candidates = BY_FIRST.get(key);
    if (candidates) {
      for (const entry of candidates) {
        if (entry.match(value)) return entry.tag;
      }
    }
  }
  if (kind === SCALAR) return DEFAULT_SCALAR_TAG;
  if (kind === SEQUENCE) return DEFAULT_SEQUENCE_TAG;
  if (kind === MAPPING) return DEFAULT_MAPPING_TAG;
  return null;
}

