  if (type === 'boolean') return 'i:' + (value ? '1' : '0');
  if (type === 'bigint') return 'i:' + value.toString();
  if (type === 'number') {
    if (Number.isNaN(value)) {
      nanCounter += 1;
      return 'nan:' + nanCounter;
    }
    if (Number.isFinite(value) && Number.isInteger(value)) {
      return 'i:' + BigInt(value).toString();
    }
    return 'f:' + String(value);
  }
  if (type === 'string') return 's:' + value;
  if (value instanceof PyBytes) return 'b:' + value.asLatin1();
  if (value instanceof PyDateTime) {
    return 'dt:' + value.isoformat() + ':' + String(value.tzMinutes);
  }
  if (value instanceof PyDate) return 'd:' + value.isoformat();
  return UNHASHABLE;
}

export function isHashable(value) {
  return hashKey(value) !== UNHASHABLE;
}

/** Insertion-ordered mapping with Python dict key semantics. */
export class PyDict {
  constructor() {
    this.entries = [];
    this.index = new Map();
  }

  get size() {
    return this.entries.length;
  }

  set(key, value) {
    const hash = hashKey(key);
    if (this.index.has(hash)) {
      this.entries[this.index.get(hash)][1] = value;
      return;
    }
    this.index.set(hash, this.entries.length);
    this.entries.push([key, value]);
  }

  has(key) {
    return this.index.has(hashKey(key));
  }

  get(key) {
    const hash = hashKey(key);
    if (!this.index.has(hash)) return undefined;
    return this.entries[this.index.get(hash)][1];
  }

  items() {
    return this.entries;
  }

  update(other) {
    for (const [key, value] of other.items()) this.set(key, value);
  }
}

/** Insertion-ordered set with the same key semantics. */
export class PySet {
  constructor() {
    this.values = [];
    this.index = new Map();
  }

  get size() {
    return this.values.length;
  }

  add(value) {
    const hash = hashKey(value);
    if (this.index.has(hash)) return;
    this.index.set(hash, this.values.length);
    this.values.push(value);
  }

  items() {
    return this.values;
  }
}

/** Raised where CPython would raise TypeError from an unorderable comparison. */
export class UnorderableError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UnorderableError';
  }
}

function isNumeric(value) {
  return typeof value === 'bigint' || typeof value === 'number'
    || typeof value === 'boolean';
}

function numeric(value) {
  if (typeof value === 'boolean') return value ? 1 : 0;
  return value;
}

function typeName(value) {
  if (value === null) return 'NoneType';
  if (typeof value === 'boolean') return 'bool';
  if (typeof value === 'bigint') return 'int';
  if (typeof value === 'number') return 'float';
  if (typeof value === 'string') return 'str';
  if (Array.isArray(value)) return 'list';
  if (value instanceof PyBytes) return 'bytes';
  if (value instanceof PyDateTime) return 'datetime.datetime';
  if (value instanceof PyDate) return 'datetime.date';
  if (value instanceof PyDict) return 'dict';
  if (value instanceof PySet) return 'set';
  return 'object';
}

function unorderable(a, b) {
  return new UnorderableError(
    `'<' not supported between instances of '${typeName(a)}' and '${typeName(b)}'`);
}

/** Code-point-wise string ordering, as Python compares str. */
function compareStrings(a, b) {
  const ai = Array.from(a);
  const bi = Array.from(b);
  const n = Math.min(ai.length, bi.length);
  for (let i = 0; i < n; i += 1) {
    const x = ai[i].codePointAt(0);
    const y = bi[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (ai.length === bi.length) return 0;
  return ai.length < bi.length ? -1 : 1;
}

function compareArrays(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i += 1) {
    const c = compareValues(a[i], b[i]);
    if (c !== 0) return c;
  }
  if (a.length === b.length) return 0;
  return a.length < b.length ? -1 : 1;
}

/** Three-way comparison following Python's rules; throws when unorderable. */
export function compareValues(a, b) {
  if (isNumeric(a) && isNumeric(b)) {
    const x = numeric(a);
    const y = numeric(b);
    if (typeof x === 'number' && Number.isNaN(x)) throw unorderable(a, b);
    if (typeof y === 'number' && Number.isNaN(y)) throw unorderable(a, b);
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
  }
  if (typeof a === 'string' && typeof b === 'string') return compareStrings(a, b);
  if (a instanceof PyBytes && b instanceof PyBytes) {
    return compareStrings(a.asLatin1(), b.asLatin1());
  }
  if (a instanceof PyDateTime && b instanceof PyDateTime) {
    const x = a.sortFields();
    const y = b.sortFields();
    if ((a.tzMinutes === null) !== (b.tzMinutes === null)) {
      throw new UnorderableError("can't compare offset-naive and offset-aware datetimes");
    }
    return compareArrays(x.map((v) => BigInt(v)), y.map((v) => BigInt(v)));
  }
  if (a instanceof PyDate && b instanceof PyDate
    && !(a instanceof PyDateTime) && !(b instanceof PyDateTime)) {
    return compareArrays([BigInt(a.year), BigInt(a.month), BigInt(a.day)],
      [BigInt(b.year), BigInt(b.month), BigInt(b.day)]);
  }
  if (Array.isArray(a) && Array.isArray(b)) return compareArrays(a, b);
  throw unorderable(a, b);
}

/** Stable sort that mirrors `sorted()`: on TypeError the original order stays. */
export function trySortPairs(pairs) {
  const decorated = pairs.map((pair, i) => ({ pair, i }));
  try {
    decorated.sort((left, right) => {
      const c = compareValues(left.pair[0], right.pair[0]);
      if (c !== 0) return c;
      return left.i - right.i;
    });
  } catch (err) {
    if (err instanceof UnorderableError) return pairs;
    throw err;
  }
  return decorated.map((item) => item.pair);
}

