/**
 * Base64 codec for the binary tag.
 *
 * Encoding follows the line-wrapping used by Python's `base64.encodebytes`
 * (76 characters per line, trailing newline); decoding follows
 * `base64.decodebytes`, which skips characters outside the alphabet.
 */

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

const REVERSE = new Map();
for (let i = 0; i < ALPHABET.length; i += 1) REVERSE.set(ALPHABET[i], i);

export class Base64Error extends Error {}

export function encodeBase64Lines(bytes) {
  let body = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    body += ALPHABET[b0 >> 2];
    body += ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
    body += i + 1 < bytes.length ? ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)] : '=';
    body += i + 2 < bytes.length ? ALPHABET[b2 & 0x3f] : '=';
  }
  let out = '';
  for (let i = 0; i < body.length; i += 76) {
    out += body.slice(i, i + 76) + '\n';
  }
  return out;
}

export function decodeBase64(text) {
  const symbols = [];
  for (const ch of text) {
    if (REVERSE.has(ch)) symbols.push(REVERSE.get(ch));
    else if (ch === '=') break;
  }
  if (symbols.length % 4 === 1) {
    throw new Base64Error('Invalid base64-encoded string: number of data characters '
      + `(${symbols.length}) cannot be 1 more than a multiple of 4`);
  }
  const bytes = [];
  for (let i = 0; i + 1 < symbols.length; i += 4) {
    const s0 = symbols[i];
    const s1 = symbols[i + 1];
    bytes.push(((s0 << 2) | (s1 >> 4)) & 0xff);
    if (i + 2 < symbols.length) {
      bytes.push(((s1 << 4) | (symbols[i + 2] >> 2)) & 0xff);
      if (i + 3 < symbols.length) {
        bytes.push(((symbols[i + 2] << 6) | symbols[i + 3]) & 0xff);
      }
    }
  }
  return Uint8Array.from(bytes);
}

/** Encode a string's code points as UTF-8 bytes. */
export function encodeUtf8(text) {
  const bytes = [];
  for (let i = 0; i < text.length;) {
    const code = text.codePointAt(i);
    i += code > 0xffff ? 2 : 1;
    if (code < 0x80) {
      bytes.push(code);
    } else if (code < 0x800) {
      bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
    } else if (code < 0x10000) {
      bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    } else {
      bytes.push(0xf0 | (code >> 18), 0x80 | ((code >> 12) & 0x3f),
        0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    }
  }
  return Uint8Array.from(bytes);
}

