/**
 * Composer: turns the event stream into a node graph, resolving anchors,
 * aliases and implicit tags.
 */

import { Parser } from './parser.mjs';
import { ComposerError } from './errors.mjs';
import { E } from './events.mjs';
import { ScalarNode, SequenceNode, MappingNode, SCALAR, SEQUENCE, MAPPING } from './nodes.mjs';
import { resolve } from './resolver.mjs';
import { reprString } from './pyrepr.mjs';

export class Composer extends Parser {
  constructor(text) {
    super(text);
    this.anchors = new Map();
  }

  getSingleNode() {
    this.getEvent();
    let document = null;
    if (!this.checkEvent(E.STREAM_END)) {
      document = this.composeDocument();
    }
    if (!this.checkEvent(E.STREAM_END)) {
      const event = this.getEvent();
      throw new ComposerError('expected a single document in the stream',
        document.startMark, 'but found another document', event.startMark);
    }
    this.getEvent();
    return document;
  }

  composeDocument() {
    this.getEvent();
    const node = this.composeNode(null, null);
    this.getEvent();
    this.anchors = new Map();
    return node;
  }

  composeNode(parent, index) {
    if (this.checkEvent(E.ALIAS)) {
      const event = this.getEvent();
      const anchor = event.anchor;
      if (!this.anchors.has(anchor)) {
        throw new ComposerError(null, null,
          `found undefined alias ${reprString(anchor)}`, event.startMark);
      }
      return this.anchors.get(anchor);
    }
    const event = this.peekEvent();
    const anchor = event.anchor === undefined ? null : event.anchor;
    if (anchor !== null && this.anchors.has(anchor)) {
      throw new ComposerError(
        `found duplicate anchor ${reprString(anchor)}; first occurrence`,
        this.anchors.get(anchor).startMark, 'second occurrence', event.startMark);
    }
    if (this.checkEvent(E.SCALAR)) return this.composeScalarNode(anchor);
    if (this.checkEvent(E.SEQUENCE_START)) return this.composeSequenceNode(anchor);
    return this.composeMappingNode(anchor);
  }

  composeScalarNode(anchor) {
    const event = this.getEvent();
    let tag = event.tag;
    if (tag === null || tag === '!') {
      tag = resolve(SCALAR, event.value, event.implicit);
    }
    const node = new ScalarNode(tag, event.value, event.startMark, event.endMark,
      event.style);
    if (anchor !== null) this.anchors.set(anchor, node);
    return node;
  }

  composeSequenceNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = resolve(SEQUENCE, null, [startEvent.implicit, false]);
    }
    const node = new SequenceNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    let index = 0;
    while (!this.checkEvent(E.SEQUENCE_END)) {
      node.value.push(this.composeNode(node, index));
      index += 1;
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }

  composeMappingNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = resolve(MAPPING, null, [startEvent.implicit, false]);
    }
    const node = new MappingNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    while (!this.checkEvent(E.MAPPING_END)) {
      const itemKey = this.composeNode(node, null);
      const itemValue = this.composeNode(node, itemKey);
      node.value.push([itemKey, itemValue]);
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }
}

