/**
 * Constructor: node graph -> Python-shaped values.
 *
 * Collections are created empty and filled in a deferred pass so that
 * self-referential documents construct the same way the reference does.
 */

import { Composer } from './composer.mjs';
import { ConstructorError } from './errors.mjs';
import { SCALAR, SEQUENCE, MAPPING } from './nodes.mjs';
import {
  PyDict, PySet, PyBytes, PyDate, PyDateTime, hashKey, UNHASHABLE,
} from './pytypes.mjs';
import { decodeBase64, Base64Error } from './base64.mjs';
import { parseTimestampParts } from './resolver.mjs';
import { reprString } from './pyrepr.mjs';

const BOOL_VALUES = new Map([
  ['yes', true], ['no', false], ['true', true], ['false', false],
  ['on', true], ['off', false],
]);

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function parseBigInt(text, base) {
  if (text.length === 0) throw new Error(`invalid literal for int() with base ${base}: ''`);
  const bigBase = BigInt(base);
  let total = 0n;
  for (const ch of text) {
    let digit;
    if (ch >= '0' && ch <= '9') digit = ch.charCodeAt(0) - 48;
    else if (ch >= 'a' && ch <= 'z') digit = ch.charCodeAt(0) - 87;
    else if (ch >= 'A' && ch <= 'Z') digit = ch.charCodeAt(0) - 55;
    else digit = -1;
    if (digit < 0 || digit >= base) {
      throw new Error(`invalid literal for int() with base ${base}: ${reprString(text)}`);
    }
    total = total * bigBase + BigInt(digit);
  }
  return total;
}

function splitOn(text, sep) {
  const parts = [];
  let current = '';
  for (const ch of text) {
    if (ch === sep) {
      parts.push(current);
      current = '';
    } else {
      current += ch;
    }
  }
  parts.push(current);
  return parts;
}

function removeUnderscores(text) {
  let out = '';
  for (const ch of text) if (ch !== '_') out += ch;
  return out;
}

export class Constructor extends Composer {
  constructor(text) {
    super(text);
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.stateGenerators = [];
    this.deepConstruct = false;
  }

