    return {
      __deferred: true,
      value: data,
      fill: () => {
        for (const item of this.constructSequence(node)) data.push(item);
      },
    };
  }

  constructYamlMap(node) {
    const data = new PyDict();
    return {
      __deferred: true,
      value: data,
      fill: () => {
        data.update(this.constructMapping(node));
      },
    };
  }

  constructYamlSet(node) {
    const data = new PySet();
    return {
      __deferred: true,
      value: data,
      fill: () => {
        const mapping = this.constructMapping(node);
        for (const [key] of mapping.items()) data.add(key);
      },
    };
  }

  constructYamlOmap(node) {
    const omap = [];
    return {
      __deferred: true,
      value: omap,
      fill: () => {
        this.fillPairs(node, omap, 'an ordered map');
      },
    };
  }

  constructYamlPairs(node) {
    const pairs = [];
    return {
      __deferred: true,
      value: pairs,
      fill: () => {
        this.fillPairs(node, pairs, 'pairs');
      },
    };
  }

  fillPairs(node, target, what) {
    if (node.kind !== SEQUENCE) {
      throw new ConstructorError(`while constructing ${what}`, node.startMark,
        `expected a sequence, but found ${node.kind}`, node.startMark);
    }
    for (const subnode of node.value) {
      if (subnode.kind !== MAPPING) {
        throw new ConstructorError(`while constructing ${what}`, node.startMark,
          `expected a mapping of length 1, but found ${subnode.kind}`,
          subnode.startMark);
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError(`while constructing ${what}`, node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark);
      }
      const [keyNode, valueNode] = subnode.value[0];
      target.push([this.constructObject(keyNode), this.constructObject(valueNode)]);
    }
  }
}

function checkDate(year, month, day) {
  if (month < 1 || month > 12) throw new Error('month must be in 1..12');
  let limit = DAYS_IN_MONTH[month - 1];
  if (month === 2 && isLeapYear(year)) limit = 29;
  if (day < 1 || day > limit) throw new Error(`day is out of range for month`);
}

function checkTime(hour, minute, second) {
  if (hour > 23) throw new Error('hour must be in 0..23');
  if (minute > 59) throw new Error('minute must be in 0..59');
  if (second > 59) throw new Error('second must be in 0..59');
}
